ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"message" : "Flights added successfully (but not really)"
}

%dw 2.0
output application/json
---
{
	notificationStatus: "ERROR",
	flightId: vars.flightId,
	error: vars.errorDescription,
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
	notificationType: "FLIGHT_UPDATE",
	recipient: {
		email: vars.passengerData.passenger_email,
		name: vars.passengerData.passenger_name
	},
	flightDetails: {
		flightId: vars.flightId,
		bookingId: vars.passengerData.booking_id,
		updatedFields: vars.updatePayload
	},
	message: "Your flight " ++ (vars.flightId as String) ++ " has been updated. Please check your booking for the latest details.",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
	message: "Flight " ++ (vars.flightId as String) ++ " updated successfully",
	updatedFlight: {
		ID: payload[0].ID,
		code: payload[0].code1,
		price: payload[0].price default 0,
		departureDate: payload[0].takeOffDate as String default "",
		origin: payload[0].fromAirport default "",
		destination: payload[0].toAirport default "",
		emptySeats: payload[0].seatsAvailable default 0,
		plane: {
			"type": payload[0].planeType default "",
			totalSeats: payload[0].totalSeats default 0
		}
	},
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}
